import * as React from "react"
import { ChevronDown } from "lucide-react"
import { cn } from "./cn"

export interface SelectProps extends React.SelectHTMLAttributes<HTMLSelectElement> {}

// A native select keeps the platform's keyboard and screen-reader behaviour. Its own arrow sits
// wherever the browser draws it (against the border in Chrome), so it is replaced by a chevron
// with the same inset as the text.
const Select = React.forwardRef<HTMLSelectElement, SelectProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div className="uhuu:relative uhuu:w-full">
        <select
          className={cn(
            "uhuu:peer uhuu:flex uhuu:h-8 uhuu:w-full uhuu:appearance-none uhuu:truncate uhuu:rounded-md uhuu:border uhuu:border-gray-200 uhuu:bg-(--uhuu-shell-surface) uhuu:py-1 uhuu:pr-8 uhuu:pl-2.5 uhuu:text-sm uhuu:text-gray-900 uhuu:outline-none uhuu:transition-colors uhuu:hover:border-gray-300 uhuu:focus:border-gray-400 uhuu:focus:ring-2 uhuu:focus:ring-gray-200 uhuu:focus:ring-offset-0 uhuu:disabled:cursor-not-allowed uhuu:disabled:opacity-50",
            className
          )}
          ref={ref}
          {...props}
        >
          {children}
        </select>
        <ChevronDown
          aria-hidden="true"
          className="uhuu:pointer-events-none uhuu:absolute uhuu:top-1/2 uhuu:right-2.5 uhuu:h-3.5 uhuu:w-3.5 uhuu:-translate-y-1/2 uhuu:text-gray-500 uhuu:peer-disabled:opacity-50"
        />
      </div>
    )
  }
)
Select.displayName = "Select"

export { Select }
