import { createContext, useContext } from 'react';
import { isDev } from './is-dev';

// Internal and scoped to the nearest shell: enabling diagnostics in one preview must not enable
// optional warnings in another. Contract failures warn regardless of this preference.
export const DiagnosticWarningsContext = createContext(false);

export function useDiagnosticWarnings() {
  const enabled = useContext(DiagnosticWarningsContext);
  const host = typeof window === 'undefined' ? undefined : (window as unknown as {
    __uhuuPreviewHost?: { enableEditorShellDevTools?: boolean };
  }).__uhuuPreviewHost;
  return enabled || Boolean(host?.enableEditorShellDevTools) || isDev();
}
